	internal static class QueryStorageNotetakee
	{
		// Token: 0x04000176 RID: 374
		internal const string QS_NOTETAKEE_COURSES_BY_STUDENT_AND_DATERANGE = "DECLARE @pid int = 5090\r\nDECLARE @startdate datetime = '2015-01-01'\r\nDECLARE @enddate datetime = '2016-01-01'\r\nDECLARE @includedroppedcourses bit = 0\r\nDECLARE @loadselfreg bit = 1\r\n\r\nDECLARE @sdate datetime = DATEADD(D, 0, DATEDIFF(D, 0, @startdate))\r\nDECLARE @edate datetime = DATEADD(D, 0, DATEDIFF(D, 0, @enddate))\r\n\r\nSELECT\t\tluc.lucourseid,luc.startdate,luc.enddate,luc.duration,luc.term,luc.subjectid,luc.externalid,luc.exemptfromdatasync AS lucexemptfromdatasync,\r\n            lucd.lookupstring AS subjectcode,lucd.altlookupstring AS subjectdescription,\r\n            luc.course,luc.timeofday,luc.[section],\r\n            luc.campus,luc.department,luc.location,luc.credits,\r\n            luc.coursenote,\r\n\t\t\tCAST(NULL AS int) AS ServiceProviderRequestID,CAST(NULL AS Datetime) AS DateAssigned,CAST(NULL AS int) AS ServiceProviderId,\r\n\t\t\tCAST(NULL AS int) AS StudentCourseAccommodationRequestId, CAST(NULL AS int) AS [status]\r\nINTO #t1\r\nFROM        courses c LEFT JOIN lucourses luc ON luc.LUCourseID=c.luCourseID\r\n\t\t\tLEFT JOIN lucoursedata lucd ON lucd.lucoursedataid=luc.subjectid\r\nWHERE       c.personID=@pid \r\n\t\t\tAND (@includedroppedcourses=1 OR (c.registrationstatus iS NULL OR NOT c.registrationstatus=2))\r\n\t\t\tAND NOT ( ( luc.enddate<@sdate ) OR (luc.startdate > @edate ) )\r\n--ORDER BY    luc.startdate,luc.duration,luc.term,lucd.altlookupstring,luc.course,luc.[section],luc.timeofday,luc.lucourseid;\r\n\r\nSELECT DISTINCT lucourseid INTO #tlucids FROM #t1 \r\n\r\n-- merge in service provider requests\r\n\r\nSELECT\t#tlucids.lucourseid,spr.ServiceProviderRequestID,spr.DateAssigned,spr.ServiceProviderId\r\nINTO #trequests\r\nFROM\t#tlucids LEFT JOIN ServiceProviderRequests spr ON spr.personid=@pid AND spr.lucourseid=#tlucids.LUCourseID\r\n\r\nUPDATE #t1 SET #t1.ServiceProviderRequestID=RAN.ServiceProviderRequestID,#t1.DateAssigned=RAN.DateAssigned,#t1.ServiceProviderId=RAN.ServiceProviderId\r\nFROM #t1 SI INNER JOIN #trequests RAN ON SI.lucourseid=RAN.lucourseid\r\n\r\n-- end merge in provider requests\r\n\r\n-- merge in self reg requests\r\n\r\nIF @loadselfreg=1 \r\nBEGIN\r\n\r\nSELECT  #tlucids.LUCourseID,sar.StudentCourseAccommodationRequestId,sar.[status]\r\nINTO #tselfreg\r\nFROM\t#tlucids LEFT JOIN StudentCourseAccommodationRequest sar ON sar.isactive=1 AND sar.personid=@pid AND sar.lucourseid=#tlucids.LUCourseID\r\nORDER BY CASE WHEN sar.[status]=8 THEN NULL ELSE sar.[status] END --make sure approved statuses are at the top - they will get picked\r\n\r\nUPDATE #t1 SET #t1.StudentCourseAccommodationRequestId=RAN.StudentCourseAccommodationRequestId,#t1.[status]=RAN.[status]\r\nFROM #t1 SI INNER JOIN #tselfreg RAN ON SI.lucourseid=RAN.lucourseid\r\n\r\nDROP TABLE #tselfreg\r\n\r\nEND\r\n\r\n-- end merge in self reg requests\r\n\r\nSELECT * FROM #t1 \r\nORDER BY    startdate,duration,term,subjectdescription,course,[section],timeofday,lucourseid\r\n\r\nDROP TABLE #t1\r\nDROP TABLE #tlucids\r\nDROP TABLE #trequests";

		// Token: 0x04000177 RID: 375
		internal const string QS_LUCIDS_WHERE_AT_LEAST_ONE_NOTETAKER_AVAILABLE = "SELECT orderid AS lucourseid INTO #tlucids FROM splitorderids(COALESCE(@lucids,''),',')\r\n\r\nDECLARE @Fields TABLE(lucid int )\r\nINSERT INTO @Fields (lucid) SELECT lucourseid FROM #tlucids\r\n\r\nSELECT lucid,lucourseid\r\nINTO #tlucids2\r\nFROM @Fields \r\nCROSS APPLY EquivalentCourses1([@Fields].lucid)\r\n\r\nSELECT DISTINCT #tlucids2.lucid,spac.serviceproviderapplicationid,spac.lucourseid\r\nFROM #tlucids2 LEFT JOIN serviceproviderapplicationcourses spac ON spac.lucourseid=#tlucids2.lucourseid\r\nWHERE spac.serviceprovidertype=128 AND (spac.registrationstatus IS NULL OR NOT spac.registrationstatus=2)\r\n\r\nDROP TABLE #tlucids\r\nDROP TABLE #tlucids2";
	}
}
